for(let i=0;i<8;i++){const a=i*Math.PI/4;const p=box(shrine,Math.cos(a)*2.65,.83,Math.sin(a)*2.65,.68,1.05,.68,mat('#83978a'));p.rotation.y=-a}
cylinder(shrine,0,.85,0,1.65,1.65,.75,mat('#647d70'),20);cylinder(shrine,0,1.42,0,.65,.82,.4,mat('#a8b39a'),16);
const rune=cylinder(shrine,0,2.05,0,.29,.45,.95,mat('#677e74'),8);rune.rotation.z=.16;
const shrineOrb=sphere(shrine,0,2.72,0,.48,mat('#374c48'),1,.82,1);shrineOrb.material=shrineOrb.material.clone();shrineOrb.material.emissive=new THREE.Color('#061714');shrineOrb.material.emissiveIntensity=.1;
const shrineRing=new THREE.Mesh(new THREE.TorusGeometry(.79,.055,8,32),mat('#d4c896'));shrineRing.position.y=2.1;shrineRing.rotation.x=Math.PI/2;shrine.add(shrineRing);
// Lanterns mark the way into the shrine.
for(const x of [-4,4]){cylinder(shrine,x,.65,4,.12,.17,1.3,woodMat,8);sphere(shrine,x,1.42,4,.2,goldMat,.8,1,.8)}

