// Lanterns mark the way into the shrine.
for(const x of [-4,4]){cylinder(shrine,x,.65,4,.12,.17,1.3,woodMat,8);sphere(shrine,x,1.42,4,.2,goldMat,.8,1,.8)}
// Hero: green travel cloak, bright tunic, round face, pointed cap and a visible sword.
const player=new THREE.Group();world.add(player);player.position.set(0,0,20);
const body=new THREE.Group();player.add(body);
const tunic=mat('#408e75'),skin=mat('#ffd0a0'),dark=mat('#31534a'),cape=mat('#24705d'),bladeMat=new THREE.MeshStandardMaterial({color:'#e4f6df',metalness:.65,roughness:.22}),bootMat=mat('#604b42');
sphere(body,0,.7,0,.42,tunic,1,.94,.85);sphere(body,0,1.34,.02,.32,skin,.94,1,.9);
const cap=new THREE.Mesh(new THREE.ConeGeometry(.29,.55,8),mat('#54a978'));cap.position.set(0,1.78,-.04);cap.rotation.z=-.12;cap.castShadow=true;body.add(cap);
sphere(body,-.115,1.39,.29,.035,dark);sphere(body,.115,1.39,.29,.035,dark);
const capeMesh=new THREE.Mesh(new THREE.ConeGeometry(.43,.88,4),cape);capeMesh.position.set(0,.66,-.32);capeMesh.rotation.x=-.19;capeMesh.castShadow=true;body.add(capeMesh);
for(const x of [-.21,.21]){const leg=box(body,x,.19,.015,.19,.34,.25,bootMat);leg.userData.leg=true}
const swordPivot=new THREE.Group();swordPivot.position.set(.35,.8,.05);body.add(swordPivot);
const swordHandle=cylinder(swordPivot,0,.08,0,.055,.055,.2,woodMat,7);const blade=box(swordPivot,0,.39,0,.13,.55,.055,bladeMat);blade.rotation.z=-.08;box(swordPivot,0,.19,0,.3,.07,.08,goldMat);swordPivot.rotation.z=-.85;
// Floating star shards, each has an animated golden halo.
const shards=[];function makeShard(x,z){const g=new THREE.Group();g.position.set(x,.8,z);world.add(g);const crystal=new THREE.Mesh(new THREE.OctahedronGeometry(.52,0),crystalMat);crystal.scale.set(.72,1.35,.72);crystal.castShadow=true;g.add(crystal);const ring=new THREE.Mesh(new THREE.TorusGeometry(.78,.035,6,24),goldMat);ring.rotation.x=Math.PI/2;g.add(ring);for(let i=0;i<3;i++){const bit=sphere(g,Math.cos(i*2.1)*.84,.12,Math.sin(i*2.1)*.84,.09,goldMat);bit.userData.orbit=i}shards.push({group:g,crystal,x,z,phase:Math.random()*6})}
makeShard(-20,5);makeShard(20,7);makeShard(10,-23);
// Gloomies: shy shadow creatures that wake up when the hero draws near.
const enemies=[];const enemyMat=new THREE.MeshStandardMaterial({color:'#596b87',roughness:.52,emissive:'#28364c',emissiveIntensity:.35});const eyeMat=new THREE.MeshStandardMaterial({color:'#f9dc91',emissive:'#ffb84c',emissiveIntensity:1.4});
function makeEnemy(x,z){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);sphere(g,0,.48,0,.49,enemyMat,1,.87,.94);sphere(g,0,.82,-.02,.37,enemyMat,1,.7,.95);for(const ex of [-.14,.14])sphere(g,ex,.88,.29,.065,eyeMat,.7,1,1);const ear1=new THREE.Mesh(new THREE.ConeGeometry(.15,.37,5),enemyMat);ear1.position.set(-.27,1.15,0);ear1.rotation.z=.45;g.add(ear1);const ear2=ear1.clone();ear2.position.x=.27;ear2.rotation.z=-.45;g.add(ear2);enemies.push({group:g,x,z,homeX:x,homeZ:z,hp:2,hit:0,phase:Math.random()*6,alive:true})}
makeEnemy(-11,11);makeEnemy(11,14);makeEnemy(-24,-5);makeEnemy(23,-16);
// Ancient stones, bench and campsite details around the clearing.
for(let i=0;i<9;i++){const a=i/9*Math.PI*2;const rock=sphere(world,Math.cos(a)*5.7,.24,Math.sin(a)*5.7,.38,stoneMat,1.2,.7,.88);rock.rotation.y=a}
const bench= new THREE.Group();bench.position.set(-9,.02,-3);bench.rotation.y=.4;world.add(bench);box(bench,0,.55,0,2,.15,.57,woodMat);for(const x of [-.75,.75])box(bench,x,.28,0,.12,.52,.52,barkLight);
for(const x of [-1.4,1.4]){cylinder(world,x,.52,17,.11,.14,1.04,woodMat,8);const flame=sphere(world,x,1.14,17,.17,goldMat,.75,1.2,.75);flame.userData.flame=true}
// Simple collision against forest trunks, shrine, pond and map edge.
const solidCircles=[...obstacles,{x:0,z:-15,r:4.15},{x:19,z:-9,r:5.15}];
function canStand(x,z){if(Math.abs(x)>32||Math.abs(z)>27)return false;for(const o of solidCircles){if((x-o.x)**2+(z-o.z)**2<(o.r+.38)**2)return false}return true}
const $=s=>document.querySelector(s);let health=3,shardCount=0,started=false,ended=false,attackTimer=0,invulnerable=0,interactCooldown=0,toastTimer=0,time=0,winTimer=0;
function hearts(){$('#hearts').innerHTML=Array.from({length:3},(_,i)=>`<span class="heart ${i>=health?'empty':''}">♥</span>`).join('')}
function showToast(text){$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=2.3}
function updateQuest(){ $('#shardCount').textContent=`${shardCount} / 3`;$('#objective').innerHTML=shardCount<3?`Find the <b>${3-shardCount} remaining star shard${3-shardCount===1?'':'s'}</b>`:'Return to the <b>old shrine</b> and press E'; }
