 if(len>.12){body.rotation.y=Math.atan2(dx,dz);for(const l of body.children.filter(c=>c.userData.leg))l.rotation.x=Math.sin(time*13+(l.position.x>0?Math.PI:0))*.48}else for(const l of body.children.filter(c=>c.userData.leg))l.rotation.x*=.8;
