if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('show')}
for(const child of world.children){if(child.userData.flame)child.scale.y=.82+Math.sin(time*8+child.position.x)*.18}
const target=new THREE.Vector3(player.position.x,0,player.position.z);camera.position.x=THREE.MathUtils.damp(camera.position.x,target.x,3.8,dt);camera.position.z=THREE.MathUtils.damp(camera.position.z,target.z+23,3.8,dt);camera.lookAt(target.x,0,target.z);
